function CopyButton({ text, label }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <button
      onClick={handleCopy}
      className="inline-flex items-center gap-1.5 px-2 py-1 rounded bg-[#2a2a35] hover:bg-[#3a3a45] transition-colors text-xs"
      title="Copy to clipboard"
    >
      {copied ? (
        <>
          <Check size={12} className="text-primary-400" />
          {label && <span className="text-primary-400">Copied</span>}
        </>
      ) : (
        <>
          <Copy size={12} className="text-gray-400" />
          {label && <span className="text-gray-400">{label}</span>}
        </>
      )}
    </button>
  );
}

