// ============================================================
// Observo -- API Client
// Centralized HTTP client for all dashboard API endpoints.
// Sends X-API-Key header when an API key is stored in localStorage.
// ============================================================

const BASE_URL = process.env.NEXT_PUBLIC_API_URL || "";
const STORAGE_KEY = "observo_api_key";

// --- Helpers ---

function getStoredApiKey(): string | null {
  try {
    return localStorage.getItem(STORAGE_KEY);
  } catch {
    return null;
  }
}

function buildHeaders(): HeadersInit {
  const headers: Record<string, string> = {};
  const apiKey = getStoredApiKey();
  if (apiKey) {
    headers["X-API-Key"] = apiKey;
  }
  return headers;
}

function buildUrl(path: string, params?: Record<string, string | number | undefined>): string {
  const url = new URL(path, BASE_URL || window.location.origin);
  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== "") {
        url.searchParams.set(key, String(value));
      }
    });
  }
  return url.toString();
}

async function request<T>(url: string): Promise<T> {
  const response = await fetch(url, { headers: buildHeaders() });
  if (!response.ok) {
    const body = await response.text().catch(() => "");
    throw new Error(
      `API error ${response.status}: ${response.statusText}${body ? ` — ${body}` : ""}`
    );
  }
  return response.json();
}

